joi_block.script:
if (any(#AirQualitySensor).airQualitySensor_carbonDioxide >= 1200 and any(#PresenceSensor).presenceSensor_presence == true) {
all(#AirPurifier).airPurifier_setAirPurifierMode("high")
all(#Speaker).speaker_speak("Carbon dioxide concentration is high and person detected.")
}

if ((#Home_WeatherProvider).weatherProvider_weather == "rain" and any(#HumiditySensor).humiditySensor_humidity >= 80) {
all(#Dehumidifier).dehumidifier_setDehumidifierMode("drying")
all(#Speaker).speaker_speak("It's raining and himidity is high")
}

if (any(#PresenceSensor).presenceSensor_presence == true and any(#SmokeDetector).smokeDetector_smoke == true) {
all(#Siren).siren_setSirenMode("fire")
all(#Speaker).speaker_speak("Evacuate")
}

if (all(#MotionSensor).motionSensor_motion == false and any(#ContactSensor).contactSensor_contact == false) {
all(#Camera).camera_captureImage()
all(#Speaker).speaker_speak("Warning")
}

phase := 0
if (phase == 0) {
wait until(any(#ContactSensor).contactSensor_contact == false)
    phase = 1
    all(#Speaker).speaker_speak("Welcome")
}
else {
all(#Speaker).speaker_speak("Welcome")
}

phase := 0
if (phase == 0) {
wait until(any(#ContactSensor).contactSensor_contact == true)
    phase = 1
    all(#Siren).siren_setSirenMode("police")
}
else {
all(#Siren).siren_setSirenMode("police")
}

phase := 0
if (phase == 0) {
wait until(any(#SmokeDetector).smokeDetector_smoke == true)
    phase = 1
    all(#Siren).siren_setSirenMode("emergency")
    delay(5 SEC)
all(#Switch).switch_off()
}
else {
all(#Siren).siren_setSirenMode("emergency")
    delay(5 SEC)
all(#Switch).switch_off()
}

phase := 0
if (phase == 0) {
wait until(any(#MotionSensor).motionSensor_motion == true)
    phase = 1
    all(#Camera).camera_captureImage()
}
else {
all(#Camera).camera_captureImage()
}

phase := 0
if (phase == 0) {
wait until(any(#PresenceSensor).presenceSensor_presence == true)
    phase = 1
    (#F1_Siren).siren_setSirenMode("emergency")
    delay(3 SEC)
(#F1_Siren).switch_off()
}
else {
(#F1_Siren).siren_setSirenMode("emergency")
    delay(3 SEC)
(#F1_Siren).switch_off()
}
